#include <iostream>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    long long pairs = (long long)n * (n - 1) / 2;

    int levels = 0;
    for (int width = 1; width < n; width = width * 2) {
        levels = levels + 1;
    }
    long long merged = (long long)n * levels;

    cout << "{greet}" << endl;
    cout << "每两条碰一次：" << pairs << " 圈" << endl;
    cout << "一层层合并：" << merged << " 圈" << endl;
    return 0;
}
